class PublicCloudInstanceInstanceActionTypeEnum(OpenStrEnum):
    """
    Instance action type

    Imperative action that can be triggered on an instance to change its administrative
    or operational state.

    Values
    LOCK - Lock the instance to prevent further actions on it, protecting it from
    accidental or unauthorized operations.
    UNLOCK - Remove a previously set lock, re-enabling actions on the instance.
    REBOOT - Restart the instance.
    RESCUE - Boot the instance into rescue mode from a rescue image so its root disk can
    be inspected or repaired.
    UNRESCUE - Return the instance from rescue mode to normal operation.
    STOP - Power off the instance; its resources remain allocated.
    START - Power on a stopped instance.
    SHELVE - Power off the instance and release its compute resources so it can be
    resumed later.
    UNSHELVE - Resume a shelved instance.
    PAUSE - Freeze a running instance, keeping its memory state in the RAM of the host.
    UNPAUSE - Return a paused instance to normal operation.
    SUSPEND - Save the memory state of a running instance to disk and stop it; its
    resources remain allocated.
    RESUME - Restore a suspended instance from its saved memory state.
    """

    LOCK = "LOCK"
    PAUSE = "PAUSE"
    REBOOT = "REBOOT"
    RESCUE = "RESCUE"
    RESUME = "RESUME"
    SHELVE = "SHELVE"
    START = "START"
    STOP = "STOP"
    SUSPEND = "SUSPEND"
