class PublicCloudAiAgentsLlmConfig(OVHModel):
    """
    The language model this agent uses to respond, including sampling settings and
    failover targets.
    """

    failover: PublicCloudAiAgentsFailoverPolicy | None = None
    """
    Which kinds of call failures trigger switching to a backup model instead of
    surfacing the error.
    """
    fallbacks: list[PublicCloudAiAgentsLlmFallback] | None = None
    """
    Ordered list of backup models tried, in turn, when the primary model fails. Empty
    means no failover.
    """
    max_context_messages: int | None = Field(default=None, alias="maxContextMessages")
    """
    How many trailing messages of a conversation go into the payload. 'None' keeps the
    historical 50. That number predates context windows measured in the hundreds of
    thousands of tokens: on a 262k-token model a 50-message cap uses a fraction of what
    is available, and everything older is dropped without a summary - the conversation
    quietly forgets rather than compacting. Raising it hands the ceiling back to the
    compaction path, which now has a declared budget to compare against.
    """
    max_tokens: int | None = Field(default=None, alias="maxTokens")
    """
    Maximum number of tokens the model may generate in a single response. Unset uses the
    provider's default.
    """
    model: str | None = None
    """
    Identifier of the model to call, for example 'gpt-5'.
    """
    provider_id: str | None = Field(default=None, alias="providerId")
    """
    Id of the connected provider to call for this model. Must reference an entry in the
    shared provider pool.
    """
    temperature: float | None = None
    """
    Sampling temperature controlling response randomness: lower values are more
    deterministic, higher values are more varied. Unset uses the provider's default.
    """
    vision: PublicCloudAiAgentsLlmFallback | None = None
    """
    Optional secondary model used to describe images when the primary model cannot see
    them. Unset means images are not described for a text-only model.
    """


