class PublicCloudAiAgentsPermissionRule(OVHModel):
    """
    One tool-permission rule: which tool calls it matches, and what to do with them.
    """

    action: PublicCloudAiAgentsPermissionRuleActionEnum
    """
    What to do with a matching call.
    """
    args: dict[str, str] | None = None
    """
    Argument constraints, as 'path-glob -> value-glob', ALL of which must hold for the
    rule to match. The call's arguments are flattened to 'path -> value' pairs before
    matching ('{'a':{'b':[1,2]}}' becomes 'a.b.0 -> 1', 'a.b.1 -> 2'), so one entry
    means 'some argument whose path matches the key has a value matching the pattern'. A
    '!' prefix on the value inverts it into '… and none of them matches', which is how
    an allowlist is written: '{'url': '!https://*.ovh.net/*'}' is every URL but ours.
    '!' flips the value test and not the quantifier: both forms ask whether SOME
    selected value satisfies the test. So a deny rule reading '{'url':
    '!https://*.ovh.net/*'}' still fires on a call carrying two URLs of which only one
    is foreign - which is the point of it. A rule about an argument that is absent
    entirely never matches, in either form: absence is not a value to have an opinion
    about, and a rule that fired on it would fire on every unrelated call.
    """
    phase: PublicCloudAiAgentsPermissionRulePhaseEnum | None = None
    """
    Whether this rule is evaluated before the call runs or after it returned. Defaults
    to 'before'.
    """
    reason: str | None = None
    """
    Why this rule exists. Shown to the model in the refusal and written to the log.
    Worth filling in: it is the only part of this rule the model can act on.
    """
    result: str | None = None
    """
    Value-glob over the text the tool returned. 'phase: after' only. Matched against the
    raw result, not flattened into paths the way 'args' is: a result is prose far more
    often than it is a shape, and an author writing a rule about one should not have to
    know whether this particular tool happened to wrap it in JSON. '*' spans everything,
    so ''*-----BEGIN * PRIVATE KEY*'' is a substring test, and a leading '!' inverts it
    exactly as it does in 'args'. A rule with no 'result' matches every result, which is
    how 'refer everything this tool brings back to the judge' is written.
    """
    tool: str | None = None
    """
    Glob over the tool name. '*' matches any run of characters, including an empty one,
    so a rule left at its default matches every tool.
    """
    triggers: list[PublicCloudAiAgentsPermissionRuleTriggerEnum] | None = None
    """
    Trigger kinds this rule applies to ('http', 'invoke', 'messaging', 'cron',
    'scheduled', 'subagent'). Empty means every trigger.
    """
    unattended: PublicCloudAiAgentsPermissionRuleActionEnum | None = None
    """
    What an 'ask' becomes on a turn with no human to ask. Defaults to 'deny'; ignored
    unless 'action' is 'ask'.
    """


