class PublicCloudInstanceInstance(OVHModel):
    """
    Compute instance

    A Public Cloud compute instance: a virtual machine provisioned from a flavor and an
    image, connected to one or more networks and backed by block volumes.

    The resource follows the standard desired-state / observed-state model:
    targetSpec holds the specification you asked for.
    currentState reflects what the compute backend actually reports.
    resourceStatus and currentTasks describe the reconciliation between the two.

    Updates are performed by sending a new targetSpec on the PUT route; the requested
    operations (rename, resize, power change, volume attach/detach, share attach/detach)
    are derived from the diff.
    """

    checksum: str
    """
    Concurrency-control checksum

    Computed hash representing the current targetSpec value. It enables optional
    optimistic concurrency control: the value returned by a GET may be sent back in the
    PUT and action payloads, and the request is then rejected with a 409 checksum-
    mismatch conflict if it no longer matches server-side (because another request
    modified the instance in the meantime). Sending no checksum skips that check and
    forces the write (last-write-wins).
    """
    created_at: Instant = Field(alias="createdAt")
    """
    Creation date of the instance, as an ISO 8601 / RFC 3339 timestamp.
    """
    current_state: PublicCloudInstanceInstanceCurrentState | None = Field(
        default=None, alias="currentState"
    )
    """
    Observed state

    Current observed state of the instance as reported by the compute backend (name,
    flavor, image, location, power state, networks, attached volumes, attached shares,
    security groups).

    It is null while the instance is still being created and no backend state is
    available yet.
    """
    current_tasks: list[CommonCurrentTask] | None = Field(
        default=None, alias="currentTasks"
    )
    """
    In-progress operations

    Ongoing asynchronous tasks reconciling currentState toward targetSpec (for example a
    create, resize, reboot, volume attach or share attach). Poll the instance until this
    list is empty and resourceStatus is READY to know the requested change has been
    applied.
    """
    id: str
    """
    Unique identifier of the instance.
    """
    resource_status: CommonResourceStatusEnum = Field(alias="resourceStatus")
    """
    Resource lifecycle status

    High-level readiness of the instance in the system (for example CREATING, READY,
    UPDATING, DELETING, ERROR).

    This is distinct from currentState.powerState, which carries the lower-level
    OpenStack administrative power state of the virtual machine.
    """
    target_spec: PublicCloudInstanceInstanceReadTargetSpec = Field(alias="targetSpec")
    """
    Desired specification

    Last target specification requested for the instance. On update, the difference
    between the previous and the new targetSpec determines the operations performed
    (rename, resize, power change, and declarative volume/share attach-detach).
    """
    updated_at: Instant = Field(alias="updatedAt")
    """
    Last modification date of the instance, as an ISO 8601 / RFC 3339 timestamp.
    """


