class PublicCloudStorageFileFileStorageTargetSpec(OVHModel):
    """
    Target specification for a file storage
    """

    create_from: PublicCloudStorageFileFileStorageCreateFrom | None = Field(
        default=None, alias="createFrom"
    )
    """
    Optional source to create the file storage from. Set at creation only; immutable.
    When omitted, an empty file storage is created
    """
    description: str | None = None
    """
    Description of the file storage
    """
    encryption: PublicCloudStorageFileFileStorageEncryption | None = None
    """
    Encryption configuration for the file storage. Set at creation only; immutable. When
    `createFrom` is set, the encryption of the snapshot's source file storage is used
    and returned here: requesting `enabled` true from a snapshot of an unencrypted file
    storage is rejected as an invalid parameter, and requesting `enabled` false from a
    snapshot of an encrypted file storage is ignored, so the new file storage is
    encrypted
    """
    location: PublicCloudCommonLocation
    """
    Desired resource location. When `createFrom` is set, `region` must be the region of
    the snapshot
    """
    name: str
    """
    Desired file storage name
    """
    protocol: PublicCloudStorageFileFileStorageProtocolEnum
    """
    File sharing protocol
    """
    share_network: PublicCloudStorageFileFileStorageShareNetworkRef | None = Field(
        default=None, alias="shareNetwork"
    )
    """
    Reference to a pre-existing share network to attach the file storage to. Required
    when `createFrom` is not set. When `createFrom` is set, it is optional: when
    omitted, the share network of the snapshot's source file storage is used and
    returned here; when sent, it must be that same share network, otherwise the request
    is rejected as an invalid parameter
    """
    share_type: PublicCloudStorageFileFileStorageTypeEnum | None = Field(
        default=None, alias="shareType"
    )
    """
    File storage type (performance tier). Required when `createFrom` is not set. When
    `createFrom` is set, it is optional: the type of the snapshot's source file storage
    is used and returned here
    """
    size: int | None = None
    """
    Size of the file storage in GB. Required when `createFrom` is not set. When
    `createFrom` is set, it is optional: when omitted, the size of the snapshot is used
    and returned here; a size smaller than the snapshot's size is rejected as an invalid
    parameter
    """


